#!/usr/bin/env node
/**
 * Price Capability Inventory — what the product may store about money on an
 * inspection, and what it may never produce.
 *
 * ── The product decision this enforces ──────────────────────────────────────
 * An inspection describes a property. The platform stores what an inspection
 * OBSERVES — category, severity, description — and it does not produce repair
 * prices, market values, or negotiation amounts. Money attached to an
 * inspection is written by the buyer or their agent (the repair request), never
 * generated by the product on their behalf.
 *
 * The reason is not that a price is forbidden. It is that a figure printed
 * under a company's letterhead is read as that company's figure, and a figure
 * the software generated is read as the industry's. Every capability shipped
 * here is a recommendation made to every user of it at once, and "what does a
 * repair cost" is not a question this product is in a position to answer. Cost
 * of work belongs to whoever does the work, or to the parties negotiating it.
 *
 * Booking, invoicing, payments and pay splits are a different subject: that is
 * the price of the INSPECTION, agreed between the tenant and their client. It
 * is inventoried below as `allowed` rather than excluded, so the line between
 * "what the engagement costs" and "what the repair costs" is written down where
 * a reader can see both sides of it.
 *
 * ── Why this is a gate and not a paragraph ──────────────────────────────────
 * A rule that lives only in prose is a rule nobody runs. What makes this one
 * worth running is that the failure it prevents is silent: a `*_cents` column
 * added to a finding-shaped table looks exactly like a `*_cents` column added
 * to an invoice, and the person adding it is not thinking about letterheads.
 *
 * ── What it can and cannot see ──────────────────────────────────────────────
 * Four surfaces, each bi-directional (an unlisted find fails; a listed entry
 * that no longer exists ALSO fails, so the inventory cannot decay into a
 * blanket permit for whatever lands on it next):
 *
 *   1. COLUMNS  — numeric columns in the Drizzle schema whose name is
 *                 money-shaped. Excludes booleans and timestamps, which are
 *                 integers too.
 *   2. FIELDS   — money-shaped keys in the shapes that define what an
 *                 inspection PERSISTS and what the editor may AUTHOR. These
 *                 are JSON keys inside `inspection_results.data`; no column
 *                 scan can see them, and that is where the repair-estimate
 *                 snapshot lived.
 *   3. CONTROLS — every render site of `MoneyInput`, the app's single
 *                 money-entry control. This is the surface that does NOT
 *                 depend on naming: a money field called `buyerFigure` still
 *                 needs a way for someone to type it, and this catches the
 *                 way. Adding a money input to a new screen shows up here even
 *                 if nothing about its name says money.
 *   4. RETIRED  — identifiers that must appear NOWHERE in the source. This is
 *                 the ratchet: a capability that was removed on purpose cannot
 *                 come back by autocomplete.
 *
 * What it cannot see: a price stored as free text in a note, a figure embedded
 * in a template's prose, an amount arriving through an untyped `Record<string,
 * unknown>`, and any money-shaped key in a file not on FIELD_FILES. The name
 * patterns below are a list of shapes someone thought of; everything they were
 * not told about reads as correct. Widen them when a new shape is found, and
 * rule on the hits BEFORE widening — a pattern that turns the gate red on
 * twenty fields at once makes twenty inventory entries the cheapest way back to
 * green, which converts open questions into recorded decisions nobody revisits.
 *
 * Usage:
 *   node scripts/check-price-capability.mjs
 *   node scripts/check-price-capability.mjs --fixture <dir>
 *   node scripts/check-price-capability.mjs --stale-probe
 *
 * `--fixture` points every scan at one directory instead of the real source, so
 * the gate can be proven to BITE against a committed probe
 * (`scripts/fixtures/price-capability-probe/`) rather than by pasting a price
 * column into tracked source and remembering to take it out. Stale-entry checks
 * are skipped in fixture mode (the real inventory is not in scope there);
 * `--stale-probe` proves that direction instead, by injecting one inventory
 * entry that matches nothing and asserting the gate says so.
 *
 * console.* is intentional — this is a build script, not server code.
 */
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative, sep } from "node:path";

const ROOT = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");

const argv = process.argv.slice(2);
const fixtureArg = argv.indexOf("--fixture");
const FIXTURE = fixtureArg === -1 ? null : join(ROOT, argv[fixtureArg + 1] ?? "");
const STALE_PROBE = argv.includes("--stale-probe");

/** A column name that is a quantity of money. Snake case, as stored. */
const MONEY_COLUMN_SHAPE =
    /(_cents$|^cents$|price|_cost|^cost_|^cost$|amount|_fee$|^fee_|^fee$|credit|estimate|discount|deposit|refund|payout|subtotal|dollar|usd)/;

/**
 * A field name that is a quantity of money. Camel case, as written in TS/Zod.
 *
 * Tested against the IDENTIFIER only, never the whole line — a `.describe()`
 * string that merely mentions the word "price" is documentation, not a field,
 * and matching prose would train people to reword comments to appease a gate.
 */
const MONEY_FIELD_SHAPE =
    /(cents|price|cost|amount|estimate|credit|payout|refund|discount|deposit|subtotal|dollar|usd|fee)/i;

/**
 * The shapes that define what an inspection PERSISTS and what the editor may
 * AUTHOR. Money inside `inspection_results.data` is JSON, so it has no column
 * to find: these files are the schema it does have.
 *
 * PCA cost items are deliberately absent. That surface is a commercial
 * property-condition assessment, where a cost table is the deliverable and the
 * assessor writes every figure in it — a different product answering a
 * different question, reviewed on its own terms. It is not invisible here: its
 * storage (`cost_items.unit_cost_cents`, `cost_items.lump_sum_cents`) is
 * inventoried under COLUMNS with that reason attached, so a reader meets the
 * exception in the inventory rather than discovering it in the code.
 */
const FIELD_FILES = [
    "server/lib/collab/results-doc.types.ts",
    "app/hooks/findings/shared.ts",
    "server/types/template-schema.ts",
    // The template's TS type and its Zod schema are two declarations of one
    // authoring surface, and only the second one decides what the API accepts.
    // Scanning the type alone let a money key be added back to the write
    // schema — with no type beside it — and read as clean.
    "server/lib/validations/template.schema.ts",
    "server/lib/validations/comment.schema.ts",
    "server/lib/validations/recommendation.schema.ts",
    "server/lib/report-repair-items.ts",
];

/** Where CONTROLS and RETIRED are searched. */
const SOURCE_ROOTS = ["server", "app", "packages"];

/** The single money-entry control. Its absence would silently empty surface 3. */
const MONEY_CONTROL_FILE = "app/components/MoneyInput.tsx";
const MONEY_CONTROL_USE = /<MoneyInput[\s/>]/;

/**
 * ── THE INVENTORY ───────────────────────────────────────────────────────────
 *
 * Every money-shaped thing the scans can see, and why it is allowed to exist.
 *
 *   disposition: 'allowed'      — this money is legitimately here. Either it is
 *                                 the price of the ENGAGEMENT (booking,
 *                                 invoice, payment, pay split) or it is a
 *                                 figure the buyer/agent wrote themselves.
 *   disposition: 'legacy-read'  — a key that exists only on records written
 *                                 before repair pricing was removed. Nothing
 *                                 writes it; readers tolerate it. Removing the
 *                                 readers is a separate decision about existing
 *                                 data, not about capability.
 *
 * A `reason` is mandatory. An entry without one is indistinguishable from a
 * shrug, and the reason is the whole artifact.
 */
const INVENTORY = [
    // ── COLUMNS: the price of the engagement ────────────────────────────────
    { kind: "column", id: "event_types.default_price_cents", disposition: "allowed",
      reason: "Booking: the default fee a tenant charges for this event type." },
    { kind: "column", id: "inspection_events.price_cents", disposition: "allowed",
      reason: "Booking: the fee agreed for this booking's event type." },
    { kind: "column", id: "inspections.price_cents", disposition: "allowed",
      reason: "Booking: denormalized cache of what the client is charged for the inspection." },
    { kind: "column", id: "inspections.discount_amount_cents", disposition: "allowed",
      reason: "Booking: a discount the tenant applied to their own fee." },
    { kind: "column", id: "inspections.deposit_required_cents", disposition: "allowed",
      reason: "Booking: the deposit the tenant asks for against their own fee." },
    { kind: "column", id: "services.price_cents", disposition: "allowed",
      reason: "Service catalogue: the tenant's list price for a service they perform." },
    { kind: "column", id: "inspection_services.price_override_cents", disposition: "allowed",
      reason: "Service catalogue: per-inspection override of the tenant's own list price." },
    { kind: "column", id: "inspection_services.price_snapshot_cents", disposition: "allowed",
      reason: "Service catalogue: the list price captured when the service was added." },

    // ── COLUMNS: invoicing, payment, pay splits ─────────────────────────────
    { kind: "column", id: "invoices.amount_cents", disposition: "allowed",
      reason: "Invoicing: what the tenant billed their client for the inspection." },
    { kind: "column", id: "invoices.amount_paid_cents", disposition: "allowed",
      reason: "Invoicing: how much of that invoice has been paid." },
    { kind: "column", id: "order_payments.amount_cents", disposition: "allowed",
      reason: "Payments: one ledger row per charge or refund against an order." },
    // `inspection_requests.total_amount_cents` was inventoried here as "the
    // quoted total on an inbound request". It was dropped: written at booking,
    // read only by its own accumulator, and never authoritative for anything —
    // the price of an order is `getEffectivePriceCents()`. The entry goes with
    // the column, because a stale permit is a permit waiting for the next thing
    // to land on that name.
    { kind: "column", id: "service_pay_rules.deduction_cents", disposition: "allowed",
      reason: "Pay splits: a fixed deduction from the inspector's share of the tenant's fee." },
    { kind: "column", id: "inspection_service_pay_splits.amount_cents", disposition: "allowed",
      reason: "Pay splits: what an inspector earned on one inspection service." },

    // ── COLUMNS: money the BUYER wrote ──────────────────────────────────────
    { kind: "column", id: "repair_request_items.requested_credit_cents", disposition: "allowed",
      reason: "The buyer's (or their agent's) own negotiation figure, typed by them in the "
            + "repair request. This is the one place a repair-related amount belongs, and it "
            + "is not the product's number." },

    // ── COLUMNS: commercial PCA, reviewed on its own terms ──────────────────
    { kind: "column", id: "cost_items.unit_cost_cents", disposition: "allowed",
      reason: "Commercial property-condition assessment: the cost table IS the deliverable and "
            + "the assessor writes every figure. A separate product answering a separate "
            + "question; not the residential repair-pricing surface this inventory governs." },
    { kind: "column", id: "cost_items.lump_sum_cents", disposition: "allowed",
      reason: "Commercial property-condition assessment: as above, assessor-authored." },

    // ── FIELDS: what an inspection persists ─────────────────────────────────
    { kind: "field", id: "server/lib/collab/results-doc.types.ts#estimateSnapshotMin", disposition: "legacy-read",
      reason: "Repair-item snapshot from before repair items carried scope only. Optional and "
            + "never written; declared so an older finding still parses." },
    { kind: "field", id: "server/lib/collab/results-doc.types.ts#estimateSnapshotMax", disposition: "legacy-read",
      reason: "Upper bound of the same retired repair-item snapshot range; same terms as the min." },
    // The four keys that used to sit here — `estimateLow` / `estimateHigh` on a
    // canned defect state and `estimateMin` / `estimateMax` on a result entry —
    // are GONE from the shape, not merely unwritten. They had no UI but were
    // still reachable by hand, and `projectResults` now drops them on the way
    // to D1 (there is no request boundary on the collab transport to refuse at).
    // The same is true of the template item's `defaultEstimateMin` /
    // `defaultEstimateMax` and an item attribute's `estimateMin` /
    // `estimateMax`: those had a request boundary, and it now REJECTS them —
    // `template.schema.ts` is `.strict()` and is scanned below.
    { kind: "field", id: "server/lib/validations/recommendation.schema.ts#estimateSnapshotMin", disposition: "legacy-read",
      reason: "Response shape of the aggregate repair-items read; mirrors the persisted key." },
    { kind: "field", id: "server/lib/validations/recommendation.schema.ts#estimateSnapshotMax", disposition: "legacy-read",
      reason: "Upper bound of the same aggregate response range; same terms as the min." },
    { kind: "field", id: "server/lib/validations/recommendation.schema.ts#estimateMinSum", disposition: "legacy-read",
      reason: "Sum of the legacy snapshots above. Zero on every finding written since repair "
            + "items became scope-only." },
    { kind: "field", id: "server/lib/validations/recommendation.schema.ts#estimateMaxSum", disposition: "legacy-read",
      reason: "Sum of the legacy upper bounds; zero for the same reason as the min sum." },
    { kind: "field", id: "server/lib/report-repair-items.ts#estimateMin", disposition: "legacy-read",
      reason: "Report projection of the legacy snapshot, in dollars. Emitted as null unless the "
            + "finding predates the change." },
    { kind: "field", id: "server/lib/report-repair-items.ts#estimateMax", disposition: "legacy-read",
      reason: "Upper bound of the same report projection; null on every post-change finding." },

    // ── CONTROLS: every screen with a money input ───────────────────────────
    { kind: "control", id: "app/components/editor/CostItemsPanel.tsx", disposition: "allowed",
      reason: "Commercial PCA cost table — assessor-authored, reviewed on its own terms." },
    { kind: "control", id: "app/components/inspector-portal/InvoiceCard.tsx", disposition: "allowed",
      reason: "Invoicing: what the tenant bills their client." },
    { kind: "control", id: "app/components/inspector-portal/ServicesCard.tsx", disposition: "allowed",
      reason: "Service catalogue pricing on an inspection." },
    { kind: "control", id: "app/components/invoices/NewInvoiceModal.tsx", disposition: "allowed",
      reason: "Invoicing: creating an invoice for the engagement." },
    { kind: "control", id: "app/components/new-inspection/ServicesStep.tsx", disposition: "allowed",
      reason: "Booking: the fee for the inspection being scheduled." },
    { kind: "control", id: "app/components/portal/sections/repair/RepairDefectRow.tsx", disposition: "allowed",
      reason: "The buyer's own credit request. This is the buyer typing their own number, which "
            + "is the only repair-related figure the product accepts. Since #275 the input is "
            + "REVEALED BY the `fund` action tag rather than always shown — a narrowing of when "
            + "it is offered, not a change to who authors it, so it stays allowed. Still no "
            + "prefill, no suggested figure and no report estimate anywhere near it." },
    { kind: "control", id: "app/components/settings/BookingPoliciesPanel.tsx", disposition: "allowed",
      reason: "Booking policy: deposit thresholds against the tenant's own fee." },
    { kind: "control", id: "app/components/settings/services/DepositWidget.tsx", disposition: "allowed",
      reason: "Booking policy: deposit amount against the tenant's own fee." },
    { kind: "control", id: "app/components/settings/CancellationFeeRow.tsx", disposition: "allowed",
      reason: "Cancellation policy: a late-cancellation or no-show fee against the tenant's own "
            + "fee, published in advance and enforceable only through their agreement clause. Not "
            + "a repair cost and not a negotiation amount — the same category as the deposit." },
    { kind: "control", id: "app/components/settings/services/ServiceFields.tsx", disposition: "allowed",
      reason: "Service catalogue: the tenant's list price." },
    { kind: "control", id: "app/routes/settings-event-types.tsx", disposition: "allowed",
      reason: "Booking: default fee per event type." },
    { kind: "control", id: "app/components/MoneyInput.test.tsx", disposition: "allowed",
      reason: "The control's own test." },
];

/**
 * Identifiers that were removed on purpose and must not reappear anywhere in
 * the source. Each line is a capability decision, not a naming preference.
 */
const RETIRED = [
    { id: "estimateMinCents",
      reason: "Repair estimate on a canned comment / repair item. A library entry reused across "
            + "every property cannot know any property's repair cost, and the figure reached the "
            + "report as the inspection company's own. The columns are dropped; do not re-add "
            + "the field under this or any other name." },
    { id: "estimateMaxCents",
      reason: "Upper bound of the same retired canned-comment estimate range; removed on the "
            + "same terms and must not return." },
    { id: "estimate_min_cents",
      reason: "The dropped column behind estimateMinCents." },
    { id: "estimate_max_cents",
      reason: "The dropped column behind estimateMaxCents." },
];

// ─────────────────────────────────────────────────────────────────────────────

const errors = [];

function fail(msg) { errors.push(msg); }

function* tsFiles(dir) {
    for (const entry of readdirSync(dir)) {
        if (entry === "node_modules" || entry === "build" || entry === "dist") continue;
        const p = join(dir, entry);
        if (statSync(p).isDirectory()) yield* tsFiles(p);
        else if (/\.tsx?$/.test(entry)) yield p;
    }
}

const rel = (p) => relative(ROOT, p).split(sep).join("/");

// ── Surface 1: schema columns ────────────────────────────────────────────────
const SCHEMA_DIR = FIXTURE ?? join(ROOT, "server", "lib", "db", "schema");
if (!existsSync(SCHEMA_DIR)) {
    console.error(`price-capability: schema dir not found: ${SCHEMA_DIR}`);
    process.exit(1);
}

const foundColumns = new Set();
let tableCount = 0;
{
    const tableRe = /sqliteTable\(\s*'([^']+)'\s*,\s*\{/g;
    // `integer('x')` / `real('x')`, minus the two integer flavours that are not
    // quantities: booleans and epoch timestamps.
    const colRe = /\b(integer|real)\(\s*'([^']+)'\s*(?:,\s*\{([^}]*)\})?\s*\)/g;
    for (const file of tsFiles(SCHEMA_DIR)) {
        const text = readFileSync(file, "utf8");
        let tm;
        while ((tm = tableRe.exec(text)) !== null) {
            tableCount++;
            const table = tm[1];
            const open = text.indexOf("{", tm.index);
            let depth = 0, end = open;
            for (let i = open; i < text.length; i++) {
                if (text[i] === "{") depth++;
                else if (text[i] === "}") { depth--; if (depth === 0) { end = i; break; } }
            }
            const body = text.slice(open, end);
            let cm;
            colRe.lastIndex = 0;
            while ((cm = colRe.exec(body)) !== null) {
                const col = cm[2];
                const opts = cm[3] ?? "";
                if (/mode:\s*'(boolean|timestamp_ms|timestamp)'/.test(opts)) continue;
                if (!MONEY_COLUMN_SHAPE.test(col)) continue;
                foundColumns.add(`${table}.${col}`);
            }
        }
    }
}
if (tableCount === 0) {
    fail("COLUMNS scan parsed ZERO tables — parser drift or wrong --fixture dir. A scan that "
       + "reads nothing reports nothing, which looks exactly like a clean repo.");
}

// ── Surface 2: money-shaped fields in the persistence/authoring shapes ───────
const fieldFileList = FIXTURE
    ? [...tsFiles(FIXTURE)].map(rel)
    : FIELD_FILES;
if (fieldFileList.length === 0) {
    fail("FIELDS scan has no files — the shape surface would silently read as clean.");
}

const foundFields = new Set();
{
    // `name:` / `name?:` at the start of a line — covers TS interface members,
    // Zod object keys and object-literal keys alike. The identifier is captured
    // and tested on its own; the rest of the line is never matched against.
    const fieldRe = /^[ \t]*(?:readonly[ \t]+)?([A-Za-z_$][A-Za-z0-9_$]*)\??[ \t]*:/;
    for (const relPath of fieldFileList) {
        const abs = join(ROOT, relPath);
        if (!existsSync(abs)) {
            fail(`FIELD_FILES names '${relPath}', which does not exist. A renamed file makes this `
               + `gate blind to the surface it was pointed at, and blind reads as clean.`);
            continue;
        }
        const text = readFileSync(abs, "utf8");
        // A Drizzle schema file's columns belong to surface 1. Reporting them
        // here too would name the same column twice under two different ids,
        // and the second one is not addressable by adding a column entry.
        if (text.includes("sqliteTable(")) continue;
        for (const line of text.split("\n")) {
            if (/^[ \t]*(\/\/|\*|\/\*)/.test(line)) continue;
            const m = fieldRe.exec(line);
            if (!m) continue;
            if (!MONEY_FIELD_SHAPE.test(m[1])) continue;
            foundFields.add(`${relPath}#${m[1]}`);
        }
    }
}

// ── Surface 3: money-entry controls ──────────────────────────────────────────
const controlRoots = FIXTURE ? [FIXTURE] : SOURCE_ROOTS.map((r) => join(ROOT, r));
if (!FIXTURE && !existsSync(join(ROOT, MONEY_CONTROL_FILE))) {
    fail(`CONTROLS scan is anchored on ${MONEY_CONTROL_FILE}, which does not exist. If the money `
       + `input was renamed, point MONEY_CONTROL_USE at the new one in the same change.`);
}
// Surfaces 3 and 4 read the same trees, so they read them ONCE. Four retired
// identifiers over three source roots was four full walks of every .ts/.tsx in
// the repo, which is the difference between a gate that lives in the
// pre-commit hook and one that gets moved out of it.
const foundControls = new Set();
const retiredHits = new Map(RETIRED.map((r) => [r.id, []]));
for (const root of controlRoots) {
    if (!existsSync(root)) continue;
    for (const file of tsFiles(root)) {
        const text = readFileSync(file, "utf8");
        if (MONEY_CONTROL_USE.test(text)) foundControls.add(rel(file));
        // Cheap pre-filter: most files mention none of the retired names, and
        // only the ones that do pay for a line-by-line pass.
        if (!RETIRED.some((r) => text.includes(r.id))) continue;
        const lines = text.split("\n");
        for (const entry of RETIRED) {
            if (!text.includes(entry.id)) continue;
            for (let i = 0; i < lines.length; i++) {
                if (!lines[i].includes(entry.id)) continue;
                // Prose describing the removal is not the removal being undone.
                if (/^[ \t]*(\/\/|\*|\/\*)/.test(lines[i])) continue;
                retiredHits.get(entry.id).push(`${rel(file)}:${i + 1}`);
            }
        }
    }
}
if (!FIXTURE && foundControls.size === 0) {
    fail("CONTROLS scan found no money inputs at all. That is not plausible in this app — the "
       + "match pattern has drifted and the surface is being reported as clean.");
}

// ── Surface 4: retired identifiers ───────────────────────────────────────────
for (const entry of RETIRED) {
    const hits = retiredHits.get(entry.id);
    if (hits.length > 0) {
        fail(`RETIRED identifier '${entry.id}' is back in the source at ${hits.slice(0, 6).join(", ")}`
           + `${hits.length > 6 ? ` (+${hits.length - 6} more)` : ""}.\n      ${entry.reason}`);
    }
}

// ── Inventory: structural validity ───────────────────────────────────────────
const VALID_KINDS = new Set(["column", "field", "control"]);
const VALID_DISPOSITIONS = new Set(["allowed", "legacy-read"]);
const inventory = STALE_PROBE
    ? [...INVENTORY, { kind: "column", id: "__probe_table.__probe_cents", disposition: "allowed",
                       reason: "--stale-probe: an entry that matches nothing, on purpose." }]
    : INVENTORY;

const byKind = { column: new Map(), field: new Map(), control: new Map() };
inventory.forEach((e, i) => {
    const label = `INVENTORY #${i + 1} (${e.id ?? "?"})`;
    if (!VALID_KINDS.has(e.kind)) fail(`${label}: invalid kind '${e.kind}'.`);
    if (!VALID_DISPOSITIONS.has(e.disposition)) fail(`${label}: invalid disposition '${e.disposition}'.`);
    if (!e.reason || e.reason.trim().length < 20) {
        fail(`${label}: missing or one-word 'reason'. The reason is the artifact — an entry `
           + `without one is a shrug that reads like a decision.`);
    }
    if (!VALID_KINDS.has(e.kind)) return;
    if (byKind[e.kind].has(e.id)) fail(`${label}: listed twice.`);
    byKind[e.kind].set(e.id, e);
});

const retiredIds = new Set(RETIRED.map((r) => r.id));
for (const e of inventory) {
    const bare = e.id.split(/[.#]/).pop();
    if (retiredIds.has(bare)) {
        fail(`INVENTORY allows '${e.id}' while RETIRED forbids '${bare}'. Two answers means a `
           + `reader takes whichever they found first.`);
    }
}
RETIRED.forEach((r, i) => {
    if (!r.reason || r.reason.trim().length < 20) {
        fail(`RETIRED #${i + 1} (${r.id ?? "?"}): missing or one-word 'reason'.`);
    }
});

// ── Coverage, both directions ────────────────────────────────────────────────
const SURFACES = [
    { kind: "column", found: foundColumns, what: "money-shaped schema column",
      how: "Add it to INVENTORY in scripts/check-price-capability.mjs with the reason it is "
         + "legitimately there — or, if it is a repair price, do not add the column." },
    { kind: "field", found: foundFields, what: "money-shaped field in an inspection shape",
      how: "This is a money value inside the inspection record. Add it to INVENTORY with a "
         + "reason, or keep the price out of the inspection." },
    { kind: "control", found: foundControls, what: "money-entry control render site",
      how: "A new screen lets someone type an amount. Add it to INVENTORY saying whose money it "
         + "is — the engagement's, or the buyer's own." },
];

for (const s of SURFACES) {
    for (const id of [...s.found].sort()) {
        if (byKind[s.kind].has(id)) continue;
        fail(`UNLISTED ${s.what}: '${id}'.\n      ${s.how}`);
    }
    // A listed entry that no longer exists is a line nobody removes otherwise,
    // and it quietly shrinks what a reader thinks this inventory covers.
    if (FIXTURE) continue;
    for (const id of byKind[s.kind].keys()) {
        if (s.found.has(id)) continue;
        fail(`STALE inventory entry: ${s.kind} '${id}' no longer exists. If it was removed, delete `
           + `the line; if it moved, update it. A stale entry is a permit waiting for the next `
           + `thing to land on that name.`);
    }
}

// ── Report ───────────────────────────────────────────────────────────────────
if (errors.length > 0) {
    console.error("\nPrice Capability Inventory FAILED:\n");
    for (const e of errors) console.error("  " + e);
    console.error(`\n${errors.length} error(s).`);
    console.error(
        "\n  The product stores what an inspection observes — category, severity, description.\n"
      + "  It does not produce repair costs, market values, or negotiation amounts; money on an\n"
      + "  inspection is written by the buyer or their agent.\n",
    );
    process.exit(1);
}

console.log(
    `price-capability: OK (${foundColumns.size} money columns of ${tableCount} tables, `
  + `${foundFields.size} money fields across ${fieldFileList.length} inspection shapes, `
  + `${foundControls.size} money-input sites, ${RETIRED.length} retired identifiers absent).`,
);
